from pathlib import Path
import pandas as pd,numpy as np
S=Path('research/truth/berlin-snapshot'); c=pd.read_csv(S/'balanced_compare.csv'); e=pd.read_csv(S/'day_edges.csv'); x=c.merge(e[['begin','edge','entered']].assign(hour=lambda z:z.begin//3600),on=['edge','hour'],how='left'); x.entered=x.entered.fillna(0); x['delta']=x.entered-x.cars; print('comparison rows',len(x),'changed',int(x.delta.ne(0).sum()),'original',x.cars.sum(),'snapshot',x.entered.sum(),'ratio',x.entered.sum()/x.real.sum(),'mean absolute hourly delta',x.delta.abs().mean(),'max',x.delta.abs().max()); h=x.groupby('hour')[['real','cars','entered']].sum(); print(h.to_string()); h.to_csv(S/'snapshot_hourly_check.csv'); R=x.pivot(index='site',columns='hour',values='real'); C=x.pivot(index='site',columns='hour',values='entered'); print('lag aggregate',[(k,np.corrcoef(R.sum(),np.roll(C.sum(),k))[0,1]) for k in [-2,-1,0,1,2]]); print('peak',h.entered.idxmax(),h.entered.max())
